import sys
code=''.join(c for c in open(sys.argv[1],encoding='utf-8').read() if c in '><+-.,[]') if len(sys.argv)>1 else ''.join(c for c in sys.stdin.read() if c in '><+-.,[]')
jump={}; st=[]
for i,c in enumerate(code):
    if c=='[': st.append(i)
    elif c==']':
        j=st.pop(); jump[i]=j; jump[j]=i
if st: raise SystemExit('unmatched [')
t=[0]*30000; p=ip=0; out=[]
while ip<len(code):
    c=code[ip]
    if c=='>': p+=1
    elif c=='<': p-=1
    elif c=='+': t[p]=(t[p]+1)&255
    elif c=='-': t[p]=(t[p]-1)&255
    elif c=='.': out.append(chr(t[p]))
    elif c=='[' and t[p]==0: ip=jump[ip]
    elif c==']' and t[p]!=0: ip=jump[ip]
    ip+=1
print(''.join(out))
